-- Forever STUwave: the totem preset cells (look, tooltips, editor)
--
-- Concept C of mockups/totem-presets-2026-10-14.html, drawn on the cells TotemPresets.lua adds to the totem tab. This
-- file is the picture and the controls; the rules (presets, switching, the step record) are TotemPresets.lua's.
--
--   * A CELL is a 38 px totem tab button wearing a ring: one arc per totem of its preset, in drop order, each in its
--     element's colour (TotemDial's textures are generated by tools/assets/generate_totem_dial.py: one texture per arc
--     and look, all the size of the button, tinted here). The preset's number sits in the middle, a "+" for a slot with
--     nothing in it (a dashed ring). A locked totem is a dashed grey arc. While a step runs the arcs that dropped glow,
--     the next one is thick with a white core and its totem's icon replaces the number, and cyan brackets stand round
--     the cell. An underline in the cell's edge colour sits under the ring.
--   * A name plate on the rail above the cell (the preset's name, the setting turns it off). A raised plate above that
--     shows ">NAME" in amber while a switch waits for combat to end, and the step count with a square for each totem
--     ("2/4") while a step runs.
--   * PENDING: the dial's border turns amber and dashed, a small amber triangle sits in its corner, its underline is
--     amber, and every element button that will change wears an amber dashed edge and triangle until the switch
--     applies. The waiting pulse (a setting) breathes the amber. When the switch applies the buttons that changed wear
--     a cyan edge for a moment (the applied flash, a setting).
--   * The dial: click = the step (a secure attribute, written out of combat by ApplyCell, in the totem tab's Sync),
--     right click or the wheel = switch preset, Shift click = edit the dial's preset (or make one on the NEW slot).
--     Right click and wheel are separate settings. Nothing here writes a secure attribute in combat: a switch queues.
--   * The EDITOR is a plain card on UIParent (never secure, nothing secure anchored to it): the name (8 letters), the
--     drop order with each row's totem and up and down arrows, DELETE (asks twice). Clicking a row's totem opens that
--     element's list of known totems, or "left out". Every change saves at once; closing just hides it. Editing is shut
--     in combat: the card closes when combat starts and refuses clicks.
--
-- Only plain frames, textures and font strings are touched in combat. Loads after TotemPresets.lua. Nothing here is
-- verified in game.

local _, FS = ...

local Dial = {}
FS.TotemDial = Dial

local MEDIA = "Interface\\AddOns\\forever-stuwave\\Media\\Textures\\"

local D = {
    BTN = 38, CHAMFER = 5,
    RING_ARCS = 4,
    PLATE_H = 12, PLATE_RISE = 6, RAISE_H = 14, RAISE_RISE = 20,
    DASH = 3, DASH_THICK = 1.4, DASH_COUNT = 5,
    BRACKET = { OFF = 2.5, LEN = 6, THICK = 1.4 },
    TICK = 0.1,                 -- seconds between the ticker's looks
    PULSE_HZ = 4,               -- radians per second of the waiting pulse
    CARD = { W = 198, ROW = 27, ROWS = 4, TOP = 56, FOOT = 30 },
    CONFIRM = 3,                -- seconds DELETE stays armed
    CHOOSER_TILE = 26,
}
Dial.D = D

local Theme = FS.Theme
local IsSecret = FS.IsSecret

local function Presets() return FS.TotemPresets end
local function Totems() return FS.TotemBar end

local function Scale()
    return (FS.Layout and FS.Layout.Scale and FS.Layout.Scale()) or 1
end

local function InCombat()
    return InCombatLockdown and InCombatLockdown() and true or false
end

local function Color(name)
    local c = Theme[name]
    if type(c) == "table" then return c end
end

local CYAN = Color("COLOR_POWER") or { 0.133, 0.878, 1, 1 }
local PINK = Color("COLOR_HEALTH") or { 1, 0.18, 0.592, 1 }
local AMBER = Color("COLOR_AMBER") or { 1, 0.7137, 0.2824, 1 }
local MUTED = Color("COLOR_MUTED") or { 0.6157, 0.5765, 0.7686, 1 }
local VIOLET = Color("COLOR_BORDER") or { 0.659, 0.333, 0.969, 1 }
local WHITE = { 1, 1, 1, 1 }
local ELEMENT = (type(Theme.COLOR_TOTEM) == "table" and Theme.COLOR_TOTEM) or {
    fire = { 1, 0.3529, 0.2353, 1 }, earth = { 0.6588, 0.8784, 0.3882, 1 },
    water = { 0.2902, 0.6588, 1, 1 }, air = { 0.8863, 0.8314, 1, 1 },
}
local ELEMENT_NAME = { fire = "Fire", earth = "Earth", water = "Water", air = "Air" }

local function Tint(texture, c, a)
    if texture then texture:SetVertexColor(c[1], c[2], c[3], a == nil and (c[4] or 1) or a) end
end

local function Rgb255(c)
    return math.floor(c[1] * 255 + 0.5), math.floor(c[2] * 255 + 0.5), math.floor(c[3] * 255 + 0.5)
end

-- A colour swatch in a tooltip line (a tinted white square).
local function Swatch(c)
    local r, g, b = Rgb255(c)
    return string.format("|TInterface\\Buttons\\WHITE8X8:9:9:0:0:8:8:0:8:0:8:%d:%d:%d|t ", r, g, b)
end

-------------------------------------------------------------------------------
-- Small pieces: edges, dashes, a plate
-------------------------------------------------------------------------------

-- A one pixel ring of four edge textures on `frame`.
local function NewEdges(frame, layer, sub)
    local edges = {}
    for i = 1, 4 do edges[i] = frame:CreateTexture(nil, layer or "OVERLAY", nil, sub or 3) end
    return edges
end

local function SeatEdges(edges, frame, thick)
    edges[1]:ClearAllPoints()
    edges[1]:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, 0)
    edges[1]:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, 0)
    edges[1]:SetHeight(thick)
    edges[2]:ClearAllPoints()
    edges[2]:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, 0)
    edges[2]:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, 0)
    edges[2]:SetHeight(thick)
    edges[3]:ClearAllPoints()
    edges[3]:SetPoint("TOPLEFT", frame, "TOPLEFT", 0, 0)
    edges[3]:SetPoint("BOTTOMLEFT", frame, "BOTTOMLEFT", 0, 0)
    edges[3]:SetWidth(thick)
    edges[4]:ClearAllPoints()
    edges[4]:SetPoint("TOPRIGHT", frame, "TOPRIGHT", 0, 0)
    edges[4]:SetPoint("BOTTOMRIGHT", frame, "BOTTOMRIGHT", 0, 0)
    edges[4]:SetWidth(thick)
end

local function SetEdges(edges, c, a)
    for i = 1, #edges do edges[i]:SetColorTexture(c[1], c[2], c[3], a) end
end

local function ShowAll(list, on)
    for i = 1, #list do
        if on then list[i]:Show() else list[i]:Hide() end
    end
end

-- The dashed edge of a button (4 sides, D.DASH_COUNT dashes each along the straight run between the chamfers) and the
-- little triangle in its top right corner, as a set of textures on `host`. Returns { dashes, tri }.
local function NewDashSet(host)
    local set = { dashes = {}, tri = {} }
    for i = 1, 4 * D.DASH_COUNT do
        local tex = host:CreateTexture(nil, "OVERLAY", nil, 4)
        tex:Hide()
        set.dashes[i] = tex
    end
    for i = 1, 4 do
        local tex = host:CreateTexture(nil, "OVERLAY", nil, 4)
        tex:Hide()
        set.tri[i] = tex
    end
    return set
end

-- Seats the set on `anchor` (design size w x h at scale s). Dashes run from the chamfer to the chamfer.
local function SeatDashSet(set, anchor, w, h, s)
    local run, cut = w - 2 * D.CHAMFER, D.CHAMFER
    local step = (run - D.DASH) / (D.DASH_COUNT - 1)
    local thick = D.DASH_THICK * s
    local n = 0
    local function place(x, y, dw, dh)
        n = n + 1
        local tex = set.dashes[n]
        tex:ClearAllPoints()
        tex:SetPoint("TOPLEFT", anchor, "TOPLEFT", x * s, -y * s)
        tex:SetSize(dw * s, dh * s)
    end
    for k = 0, D.DASH_COUNT - 1 do
        local at = cut + k * step
        place(at, 0.4, D.DASH, D.DASH_THICK)                       -- top
        place(w - D.DASH_THICK - 0.4, at, D.DASH_THICK, D.DASH)    -- right
        place(at, h - D.DASH_THICK - 0.4, D.DASH, D.DASH_THICK)    -- bottom
        place(0.4, at, D.DASH_THICK, D.DASH)                       -- left
    end
    local widths = { 6, 4.5, 3, 1.5 }
    for i, width in ipairs(widths) do
        local tex = set.tri[i]
        tex:ClearAllPoints()
        tex:SetPoint("TOPLEFT", anchor, "TOPLEFT", (w - 10 + (6 - width) / 2) * s, -(3 + (i - 1) * 1.4) * s)
        tex:SetSize(width * s, 1.4 * s)
    end
    set.thick = thick
end

local function PaintDashSet(set, c, a, show)
    for _, tex in ipairs(set.dashes) do
        tex:SetColorTexture(c[1], c[2], c[3], a)
        if show then tex:Show() else tex:Hide() end
    end
    for _, tex in ipairs(set.tri) do
        tex:SetColorTexture(c[1], c[2], c[3], show and 1 or 0)
        if show then tex:Show() else tex:Hide() end
    end
end

-- The plate: a dark fill with a one pixel border, a text, and up to four squares (the step count).
local function NewPlate(parent, level)
    local plate = CreateFrame("Frame", nil, parent)
    if plate.SetFrameLevel and parent.GetFrameLevel then plate:SetFrameLevel(parent:GetFrameLevel() + level) end
    plate.fill = plate:CreateTexture(nil, "BACKGROUND")
    plate.fill:SetAllPoints(plate)
    plate.fill:SetColorTexture(0.051, 0.024, 0.125, 0.94)
    plate.edges = NewEdges(plate, "BORDER", 0)
    plate.text = plate:CreateFontString(nil, "OVERLAY")
    plate.squares = {}
    for i = 1, D.RING_ARCS do
        local sq = plate:CreateTexture(nil, "OVERLAY", nil, 2)
        sq:Hide()
        plate.squares[i] = sq
    end
    plate:Hide()
    return plate
end

-- Fills a plate: `text` in `c`, squares `{ { c, state } ... }` before it (done 1, next .55, wait .2), right aligned at
-- (0, 0) of its anchor or centred, at design size. Returns nothing; the caller anchors it.
local function SetPlate(plate, o, s)
    local text = o.text or ""
    local sq = o.squares or {}
    local pw = #sq > 0 and (#sq * 7 + 4) or 0
    local w = (o.wide and (#text * 6.7 + 10) or (#text * 6.1 + 7)) + pw
    local h = o.height
    plate:SetSize(w * s, h * s)
    SeatEdges(plate.edges, plate, math.max(1, s))
    SetEdges(plate.edges, o.color, o.edgeAlpha or 0.9)
    Theme.ApplyMono(plate.text, math.floor((o.wide and 11 or 10) * s + 0.5), o.textColor or WHITE)
    plate.text:ClearAllPoints()
    plate.text:SetPoint("LEFT", plate, "LEFT", (o.wide and 5 or 3.5) * s + pw * s, 0)
    plate.text:SetText(text)
    for i, square in ipairs(plate.squares) do
        local item = sq[i]
        if item then
            local c, state = item[1], item[2]
            square:ClearAllPoints()
            square:SetPoint("LEFT", plate, "LEFT", (4 + (i - 1) * 7) * s, 0)
            square:SetSize(5 * s, 5 * s)
            square:SetColorTexture(c[1], c[2], c[3], state == "done" and 1 or state == "next" and 0.55 or 0.2)
            square:Show()
        else
            square:Hide()
        end
    end
    plate:Show()
end

-------------------------------------------------------------------------------
-- A cell's state, from the rules
-------------------------------------------------------------------------------

-- What a cell shows right now, apart from where and how it is drawn:
-- { cell, index, preset, name, digit, arcs = { { element, entry, locked, state } }, k, total, pending, pendingName,
--   stepping, next (the entry about to drop) }
function Dial.StateOf(cell)
    local PS = Presets()
    local st = { cell = cell, arcs = {}, k = 0, total = 0 }
    local index = PS.Active()
    local preset = PS.CellPreset(cell)
    st.index, st.preset = index, preset
    st.name = preset and preset.name or (cell == "gnarly" and "UNSET" or "NEW")
    local entries = PS.Entries(preset)
    local k, total = PS.Progress(cell)
    st.k, st.total = k, total
    st.stepping = k > 0
    local j = 0
    for _, entry in ipairs(entries) do
        local item = { element = entry.element, entry = entry, locked = not entry.known }
        if not entry.known then
            item.state = "locked"
        elseif not st.stepping then
            item.state = "idle"
        elseif j < k then
            item.state = "done"
            j = j + 1
        elseif j == k then
            item.state = "next"
            st.next = entry
            j = j + 1
        else
            item.state = "wait"
            j = j + 1
        end
        st.arcs[#st.arcs + 1] = item
    end
    st.empty = #entries == 0 or not preset
    if cell == "gnarly" then
        st.digit = "!"
    else
        st.digit = st.empty and "+" or tostring(index)
    end
    if cell == "dial" then
        local pending = PS.Pending()
        if pending then
            st.pending = pending
            local target = PS.Get(pending)
            st.pendingName = target and target.name or "NEW"
        end
    end
    return st
end

-------------------------------------------------------------------------------
-- Building a cell (once per button, re-seated on every scale)
-------------------------------------------------------------------------------

local function ArcPath(n, i, kind)
    return MEDIA .. "totem_dial_n" .. n .. "_" .. i .. "_" .. kind .. ".tga"
end

local Paint

local function OnEnter(self)
    self.fsHover = true
    Paint(self)
end

local function OnLeave(self)
    self.fsHover = false
    Paint(self)
end

-- A click event that counts as a press of the cell: the one the secure click acts on (the key down when the client
-- acts on key down, the release otherwise).
local function IsPressEvent(down)
    local useDown = false
    if C_CVar and C_CVar.GetCVar then
        local ok, value = pcall(C_CVar.GetCVar, "ActionButtonUseKeyDown")
        useDown = ok and value == "1"
    end
    return (down and true or false) == useDown
end

local function ShiftDown()
    return IsShiftKeyDown and IsShiftKeyDown() and true or false
end

local function AltDown()
    return IsAltKeyDown and IsAltKeyDown() and true or false
end

local function OnClick(self, mouseButton, down)
    local cell = self.fsKey
    local PS = Presets()
    if mouseButton == "LeftButton" then
        -- an Alt click (alone or with Ctrl) is blanked in ApplyCell and drops nothing: no press, flash or sound for it
        if AltDown() and not ShiftDown() then return end
        if ShiftDown() then
            if not down and cell == "dial" then Dial.EditActive() end
            if not down and cell == "gnarly" then Dial.EditGnarly() end
        elseif IsPressEvent(down) then
            PS.NotePress(cell)
        end
    elseif mouseButton == "RightButton" and not down and cell == "dial" then
        if PS.Setting(PS.SETTINGS.dialRight) then PS.Cycle(1) end
    end
end

local function OnWheel(self, delta)
    local PS = Presets()
    if self.fsKey ~= "dial" or not PS.Setting(PS.SETTINGS.dialWheel) then return end
    if type(delta) ~= "number" or IsSecret(delta) or delta == 0 then return end
    PS.Cycle(delta > 0 and 1 or -1)
end

-- Runs from TotemBar's StyleButton on every seat: builds the face once and seats it at `scale`.
function Dial.StyleCell(button, textHost, scale)
    local s = scale or Scale()
    local size = D.BTN * s
    if button.icon then button.icon:Hide() end
    if button.fsGlyph then button.fsGlyph:Hide() end

    if not button.fsArcs then
        button.fsArcs = {}
        for i = 1, D.RING_ARCS do
            local main = textHost:CreateTexture(nil, "OVERLAY", nil, 1)
            main:SetAllPoints(button)
            main:Hide()
            local core = textHost:CreateTexture(nil, "OVERLAY", nil, 2)
            core:SetAllPoints(button)
            core:Hide()
            button.fsArcs[i] = { main = main, core = core }
        end
        button.fsEmpty = textHost:CreateTexture(nil, "OVERLAY", nil, 1)
        button.fsEmpty:SetAllPoints(button)
        button.fsEmpty:SetTexture(MEDIA .. "totem_dial_empty.tga")
        button.fsEmpty:Hide()
        button.fsDigit = textHost:CreateFontString(nil, "OVERLAY")
        button.fsNext = textHost:CreateTexture(nil, "OVERLAY", nil, 3)
        button.fsNext:SetTexCoord(0.07, 0.93, 0.07, 0.93)
        button.fsNext:Hide()
        button.fsBar = textHost:CreateTexture(nil, "OVERLAY", nil, 2)
        button.fsBar:SetColorTexture(1, 1, 1, 1)
        button.fsTint = Theme.AddCut2Texture(button, Theme.SLICE_CUT2_BUTTON_TEXTURE, { 1, 1, 1, 0 }, "BACKGROUND", -7)
        button.fsDashes = NewDashSet(textHost)
        button.fsBrackets = {}
        for i = 1, 8 do
            local tex = textHost:CreateTexture(nil, "OVERLAY", nil, 5)
            tex:Hide()
            button.fsBrackets[i] = tex
        end
        button.fsRail = NewPlate(button, 7)
        button.fsRaise = NewPlate(button, 8)
        button:EnableMouseWheel(true)
        button:HookScript("OnEnter", OnEnter)
        button:HookScript("OnLeave", OnLeave)
        button:HookScript("OnClick", OnClick)
        button:HookScript("OnMouseWheel", OnWheel)
    end

    -- ring centre: 2 design px above the button's centre
    button.fsDigit:ClearAllPoints()
    button.fsDigit:SetPoint("CENTER", button, "CENTER", 0, 2 * s)
    Theme.ApplyMono(button.fsDigit, math.floor(13 * s + 0.5), WHITE)
    button.fsNext:ClearAllPoints()
    button.fsNext:SetPoint("CENTER", button, "CENTER", 0, 2 * s)
    button.fsNext:SetSize(13 * s, 13 * s)
    button.fsBar:ClearAllPoints()
    button.fsBar:SetPoint("BOTTOMLEFT", button, "BOTTOMLEFT", 5 * s, 3 * s)
    button.fsBar:SetPoint("BOTTOMRIGHT", button, "BOTTOMRIGHT", -5 * s, 3 * s)
    button.fsBar:SetHeight(2 * s)
    SeatDashSet(button.fsDashes, button, D.BTN, D.BTN, s)

    -- brackets: two strokes at each corner, standing 2.5 px outside the face
    local o, len, th = D.BRACKET.OFF * s, D.BRACKET.LEN * s, D.BRACKET.THICK * s
    local corners = {
        { "TOPLEFT", -o, o, 1, -1 }, { "TOPRIGHT", o, o, -1, -1 },
        { "BOTTOMLEFT", -o, -o, 1, 1 }, { "BOTTOMRIGHT", o, -o, -1, 1 },
    }
    for i, corner in ipairs(corners) do
        local point, x, y, dx, dy = corner[1], corner[2], corner[3], corner[4], corner[5]
        local h, v = button.fsBrackets[i * 2 - 1], button.fsBrackets[i * 2]
        h:ClearAllPoints()
        h:SetPoint(point, button, point, x, y)
        h:SetSize(len, th)
        v:ClearAllPoints()
        v:SetPoint(point, button, point, x, y)
        v:SetSize(th, len)
    end

    -- plates: the name plate on the rail, the raised one above it
    button.fsRail:ClearAllPoints()
    button.fsRail:SetPoint("BOTTOM", button, "TOP", 0, D.PLATE_RISE * s)
    button.fsRaise:ClearAllPoints()
    button.fsRaise:SetPoint("BOTTOMRIGHT", button, "TOPRIGHT", 2 * s, D.RAISE_RISE * s)
    Dial.SeatMarks(s)
    return size
end

-------------------------------------------------------------------------------
-- Painting a cell
-------------------------------------------------------------------------------

local function EdgeColor(button)
    return button.fsHot and PINK or CYAN
end

local function PaintArcs(button, st)
    local n = #st.arcs
    for i = 1, D.RING_ARCS do
        local a, item = button.fsArcs[i], st.arcs[i]
        if item then
            local c = item.locked and MUTED or ELEMENT[item.element] or WHITE
            local kind, alpha, core = "t", 0.55, false
            if item.locked then
                kind, alpha = "d", 0.6
            elseif item.state == "done" then
                kind, alpha = "g", 1
            elseif item.state == "next" then
                kind, alpha, core = "k", 0.9, true
            elseif item.state == "wait" then
                alpha = 0.25
            end
            local path = ArcPath(n, i, kind)
            if a.path ~= path then
                a.main:SetTexture(path)
                a.path = path
            end
            Tint(a.main, c, alpha)
            a.main:Show()
            if core then
                local corePath = ArcPath(n, i, "c")
                if a.corePath ~= corePath then
                    a.core:SetTexture(corePath)
                    a.corePath = corePath
                end
                Tint(a.core, WHITE, 0.9)
                a.core:Show()
            else
                a.core:Hide()
            end
        else
            a.main:Hide()
            a.core:Hide()
            a.path, a.corePath = nil, nil
        end
    end
    if n == 0 then
        Tint(button.fsEmpty, MUTED, 0.6)
        button.fsEmpty:Show()
    else
        button.fsEmpty:Hide()
    end
end

-- The amber of a waiting switch breathes when the pulse is on.
local function PulseAlpha()
    local PS = Presets()
    if not PS.Setting(PS.SETTINGS.waitPulse) then return 1 end
    local now = GetTime and GetTime() or 0
    return 0.62 + 0.38 * math.sin(now * D.PULSE_HZ)
end

function Paint(button)
    if not (button and button.fsArcs) then return end
    local PS = Presets()
    local st = Dial.StateOf(button.fsKey)
    button.fsState = st
    local s = Scale()
    PaintArcs(button, st)

    -- the middle: the next totem's icon while a step runs, else the preset's number
    local nextEntry = st.next
    if nextEntry and nextEntry.icon then
        button.fsNext:SetTexture(nextEntry.icon)
        button.fsNext:Show()
        button.fsDigit:Hide()
    else
        button.fsNext:Hide()
        button.fsDigit:SetText(st.digit)
        local c = st.empty and MUTED or WHITE
        button.fsDigit:SetTextColor(c[1], c[2], c[3], 1)
        button.fsDigit:Show()
    end

    -- the border, the underline and the tint
    local edge = EdgeColor(button)
    local pending = st.pending ~= nil
    local alpha = PulseAlpha()
    local skin = button.fsSkin
    local ring = skin and skin.border and skin.border.ring
    local glow = skin and skin.glow
    local age = PS.PressAge(button.fsKey)
    local pressed = button.fsKey == "gnarly" and age ~= nil and age < PS.P.PRESS_FLASH
        and PS.Setting(PS.SETTINGS.gnarlyFlash)
    local lit = button.fsHover or st.stepping or pressed
    if pending then
        if ring then ring:SetVertexColor(AMBER[1], AMBER[2], AMBER[3], 0) end
        if glow then glow:SetVertexColor(AMBER[1], AMBER[2], AMBER[3], 0) end
        PaintDashSet(button.fsDashes, AMBER, 0.9 * alpha, true)
        Tint(button.fsBar, AMBER, 0.9 * alpha)
    else
        if ring then
            ring:SetVertexColor(edge[1], edge[2], edge[3], pressed and 1 or button.fsHot and 0.8 or (lit and 0.9 or 0.5))
        end
        if glow then glow:SetVertexColor(edge[1], edge[2], edge[3], pressed and 0.8 or (lit and 0.35 or 0)) end
        PaintDashSet(button.fsDashes, AMBER, 0, false)
        Tint(button.fsBar, edge, button.fsHot and 0.9 or 0.85)
    end
    if button.fsHot then
        button.fsTint:SetVertexColor(PINK[1], PINK[2], PINK[3], pressed and 0.4 or 0.1)
    elseif button.fsHover then
        button.fsTint:SetVertexColor(CYAN[1], CYAN[2], CYAN[3], 0.1)
    else
        button.fsTint:SetVertexColor(1, 1, 1, 0)
    end
    for i, tex in ipairs(button.fsBrackets) do
        tex:SetColorTexture(CYAN[1], CYAN[2], CYAN[3], 1)
        if nextEntry then tex:Show() else tex:Hide() end
    end

    -- the plates
    if PS.Setting(PS.SETTINGS.dialPlate) then
        SetPlate(button.fsRail, { text = st.name, color = pending and AMBER or edge, textColor = WHITE,
            height = D.PLATE_H }, s)
    else
        button.fsRail:Hide()
    end
    if pending then
        SetPlate(button.fsRaise, { text = ">" .. st.pendingName, color = AMBER, textColor = AMBER, wide = true,
            height = D.RAISE_H, edgeAlpha = 0.85 }, s)
    elseif st.stepping then
        local squares = {}
        for i, item in ipairs(st.arcs) do
            if not item.locked then
                local state = item.state
                squares[#squares + 1] = { ELEMENT[item.element] or WHITE, state }
            end
        end
        SetPlate(button.fsRaise, { text = st.k .. "/" .. st.total, color = edge, textColor = WHITE, wide = true,
            height = D.RAISE_H, edgeAlpha = 0.85, squares = squares }, s)
    else
        button.fsRaise:Hide()
    end
end
Dial.Paint = Paint

-------------------------------------------------------------------------------
-- Marks on the element buttons: what is about to change, and what just did
-------------------------------------------------------------------------------

local marks = {}        -- element -> { frame, edges, dashes }

local function EnsureMark(element)
    local m = marks[element]
    if m then return m end
    local tb = Totems()
    local button = tb and tb.Button and tb.Button(element)
    if not button then return nil end
    local frame = CreateFrame("Frame", nil, button)
    if frame.SetFrameLevel and button.GetFrameLevel then frame:SetFrameLevel(button:GetFrameLevel() + 6) end
    frame:SetAllPoints(button)
    m = { frame = frame, edges = NewEdges(frame, "OVERLAY", 4), dashes = NewDashSet(frame), button = button }
    ShowAll(m.edges, false)
    frame:Hide()
    marks[element] = m
    return m
end

function Dial.SeatMarks(s)
    for _, element in ipairs(Presets().P.ELEMENTS) do
        local m = EnsureMark(element)
        if m then
            SeatEdges(m.edges, m.frame, 1.6 * s)
            SeatDashSet(m.dashes, m.frame, D.BTN, D.BTN, s)
        end
    end
end

-- kind: nil (none), "cyan" (just changed) or "amber" (will change)
local function SetMark(element, kind)
    local m = EnsureMark(element)
    if not m then return end
    if m.kind == kind and kind ~= "amber" then return end
    m.kind = kind
    if kind == "cyan" then
        SetEdges(m.edges, CYAN, 1)
        ShowAll(m.edges, true)
        PaintDashSet(m.dashes, AMBER, 0, false)
        m.frame:Show()
    elseif kind == "amber" then
        ShowAll(m.edges, false)
        PaintDashSet(m.dashes, AMBER, 0.9 * PulseAlpha(), true)
        m.frame:Show()
    else
        ShowAll(m.edges, false)
        PaintDashSet(m.dashes, AMBER, 0, false)
        m.frame:Hide()
    end
end

-- The mark an element button wears now: "cyan" (just changed), "amber" (will change) or nil.
function Dial.MarkKind(element)
    local m = marks[element]
    return m and m.kind or nil
end

local function PaintMarks()
    local PS = Presets()
    local want = {}
    local pending = PS.Pending()
    if pending then
        for _, element in ipairs(PS.WouldChange(pending)) do want[element] = "amber" end
    else
        local applied = PS.P.applied
        if applied and applied.at and PS.Setting(PS.SETTINGS.appliedFlash) then
            local now = GetTime and GetTime() or 0
            if now - applied.at < PS.P.APPLIED_FLASH then
                for _, element in ipairs(applied.elements) do want[element] = "cyan" end
            end
        end
    end
    for _, element in ipairs(PS.P.ELEMENTS) do SetMark(element, want[element]) end
end

-------------------------------------------------------------------------------
-- Tooltips
-------------------------------------------------------------------------------

local function Line(tip, text, c, wrap)
    tip:AddLine(text, c[1], c[2], c[3], wrap and true or false)
end

local GOLD = { 1, 0.82, 0 }

function Dial.Tooltip(button)
    local tip = GameTooltip
    if not tip then return end
    local PS = Presets()
    if FS.FrameHelpers and FS.FrameHelpers.AnchorTooltip then FS.FrameHelpers.AnchorTooltip(button) end
    local cell = button.fsKey
    local st = Dial.StateOf(cell)
    local idle = PS.P.STEP_IDLE
    if cell == "dial" then
        if not st.preset then
            Line(tip, "PRESET " .. st.index .. ": NEW", WHITE)
            Line(tip, "Empty. Shift click the dial to make one from your totem buttons.", MUTED, true)
        else
            Line(tip, "PRESET DIAL: " .. st.index .. " " .. st.name, WHITE)
            Dial.PresetLines(tip, st.preset)
            local how = { "Click: drop the next totem." }
            if PS.Setting(PS.SETTINGS.dialRight) and PS.Setting(PS.SETTINGS.dialWheel) then
                how[#how + 1] = "Right click or wheel: next preset."
            elseif PS.Setting(PS.SETTINGS.dialRight) then
                how[#how + 1] = "Right click: next preset."
            elseif PS.Setting(PS.SETTINGS.dialWheel) then
                how[#how + 1] = "Wheel: next preset."
            end
            how[#how + 1] = "Shift click: edit."
            Line(tip, table.concat(how, " "), GOLD, true)
            Line(tip, "Starts over after combat ends or a " .. idle .. " s pause.", CYAN, true)
        end
        if st.pending then
            Line(tip, "Waiting for combat to end: " .. st.pendingName, AMBER, true)
        end
    elseif cell == "gnarly" then
        if not st.preset then
            Line(tip, "GNARLY PRESET: NONE", PINK)
            Line(tip, "Choose one in the settings, or open a preset (Shift click the dial) and press USE AS GNARLY "
                .. "PRESET.", MUTED, true)
        else
            Line(tip, "GNARLY PRESET: " .. st.name, PINK)
            Dial.PresetLines(tip, st.preset)
            Line(tip, "Click: drop the next totem. Always ready, even in combat.", GOLD, true)
            Line(tip, "Starts over after combat ends or a " .. idle .. " s pause.", CYAN, true)
        end
    end
    tip:Show()
end

-- The preset's totems as numbered lines in drop order, then the elements it leaves out, muted.
function Dial.PresetLines(tip, preset)
    local PS = Presets()
    local entries = PS.Entries(preset)
    local used = {}
    for i, entry in ipairs(entries) do
        used[entry.element] = true
        local text = i .. " " .. Swatch(ELEMENT[entry.element] or WHITE) .. entry.name
        if entry.known then
            Line(tip, text, WHITE)
        else
            Line(tip, text .. " (level " .. entry.level .. ")", MUTED)
        end
    end
    for _, element in ipairs(PS.P.ELEMENTS) do
        if not used[element] then
            Line(tip, Swatch(ELEMENT[element]) .. ELEMENT_NAME[element] .. ": left out", MUTED)
        end
    end
end

-------------------------------------------------------------------------------
-- The cell's secure attributes (out of combat, from the totem tab's Sync)
-------------------------------------------------------------------------------

-- Every modifier click that edits instead of dropping: shift, alt, and each combination that holds one of them with
-- another modifier (a combo with no attribute of its own falls back to the plain type1 and would drop a totem).
-- Blizzard's SecureTemplates builds the prefix only in the order alt-ctrl-shift-.
local EDIT_CLICKS = { "shift-type1", "alt-type1", "alt-shift-type1", "alt-ctrl-type1", "alt-ctrl-shift-type1",
    "ctrl-shift-type1" }

local function ClearAttributes(button)
    for _, name in ipairs({ "type1", "macrotext1", "type2", "ctrl-type1" }) do
        button:SetAttribute(name, nil)
    end
    for _, name in ipairs(EDIT_CLICKS) do button:SetAttribute(name, nil) end
end

function Dial.ApplyCell(button, def)
    local PS = Presets()
    button.fsKey = def.key
    button.fsHot = def.hot and true or false
    local text = PS.StepText(PS.CellPreset(def.key))
    local key = text or ""
    if button.fsAttrKey ~= key then
        ClearAttributes(button)
        if text then
            button:SetAttribute("type1", "macro")
            button:SetAttribute("macrotext1", text)
        end
        -- Shift and Alt clicks (alone or with another modifier) are ours (edit): an empty type means they never drop
        for _, name in ipairs(EDIT_CLICKS) do button:SetAttribute(name, "") end
        button.fsAttrKey = key
    end
    button.fsColor = { (def.hot and PINK or CYAN)[1], (def.hot and PINK or CYAN)[2], (def.hot and PINK or CYAN)[3] }
end

-------------------------------------------------------------------------------
-- The editor
-------------------------------------------------------------------------------

local card, chooser

local function Mono(fs, size, c)
    Theme.ApplyMono(fs, math.floor(size * Scale() + 0.5), c or WHITE)
end

local function NewButton(parent, w, h)
    local b = CreateFrame("Button", nil, parent)
    b:SetSize(w, h)
    b.fill = b:CreateTexture(nil, "BACKGROUND")
    b.fill:SetAllPoints(b)
    b.fill:SetColorTexture(0.051, 0.024, 0.125, 0.8)
    b.edges = NewEdges(b, "BORDER", 0)
    b.text = b:CreateFontString(nil, "OVERLAY")
    b.text:SetPoint("CENTER", b, "CENTER", 0, 0)
    b:RegisterForClicks("LeftButtonUp")
    return b
end

local function StyleButton(b, c, text, size)
    SeatEdges(b.edges, b, math.max(1, Scale()))
    SetEdges(b.edges, c, 0.8)
    Mono(b.text, size or 9, c == MUTED and MUTED or WHITE)
    b.text:SetText(text)
end

local function CloseChooser()
    if chooser and chooser:IsShown() then chooser:Hide() end
end

function Dial.CloseEditor()
    CloseChooser()
    if card and card:IsShown() then card:Hide() end
end

local function ElementOrder(preset)
    local out, used = {}, {}
    for _, element in ipairs(preset.order) do
        out[#out + 1] = element
        used[element] = true
    end
    for _, element in ipairs(Presets().P.ELEMENTS) do
        if not used[element] then out[#out + 1] = element end
    end
    return out
end

local function Refuse(why)
    if why and UIErrorsFrame and UIErrorsFrame.AddMessage then UIErrorsFrame:AddMessage(why, 1, 0.3, 0.3) end
end

-- the list of known totems for a row: tiles for each, and "left out"
local function OpenChooser(row)
    local PS = Presets()
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    if not chooser then
        chooser = CreateFrame("Frame", "FSTotemChooser", UIParent)
        chooser:SetFrameStrata("DIALOG")
        chooser:SetFrameLevel(card:GetFrameLevel() + 10)
        chooser:EnableMouse(true)
        chooser.fill = chooser:CreateTexture(nil, "BACKGROUND")
        chooser.fill:SetAllPoints(chooser)
        chooser.fill:SetColorTexture(0.051, 0.024, 0.125, 0.97)
        chooser.edges = NewEdges(chooser, "BORDER", 0)
        chooser.tiles = {}
        chooser:Hide()
    end
    local s = Scale()
    local element, index = row.fsElement, card.fsIndex
    local tb = Totems()
    local list = tb.KnownList(element)
    local items = {}
    for _, item in ipairs(list) do
        local base = PS.BaseOf(element, item)
        if base then items[#items + 1] = { base = base, id = item.id, icon = item.icon, name = item.name } end
    end
    items[#items + 1] = { leave = true }
    local size, gap = D.CHOOSER_TILE * s, 3 * s
    chooser:SetSize((#items * D.CHOOSER_TILE + (#items + 1) * 3) * s, (D.CHOOSER_TILE + 6) * s)
    SeatEdges(chooser.edges, chooser, math.max(1, s))
    SetEdges(chooser.edges, ELEMENT[element] or VIOLET, 0.85)
    local preset = PS.Get(index)
    local current = preset and preset.picks[element]
    for i = 1, math.max(#items, #chooser.tiles) do
        local tile = chooser.tiles[i]
        if not tile then
            tile = CreateFrame("Button", nil, chooser)
            tile:RegisterForClicks("LeftButtonUp")
            tile.icon = tile:CreateTexture(nil, "ARTWORK")
            tile.icon:SetAllPoints(tile)
            tile.icon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
            tile.mark = tile:CreateTexture(nil, "OVERLAY")
            tile.text = tile:CreateFontString(nil, "OVERLAY")
            tile.text:SetPoint("CENTER", tile, "CENTER", 0, 0)
            tile:SetScript("OnClick", function(self)
                local edit = PS.SetTotem(card.fsIndex, self.fsElement, self.fsBase)
                if edit == false then return end
                CloseChooser()
                Dial.RefreshCard()
            end)
            tile:SetScript("OnEnter", function(self)
                if self.fsSpell and GameTooltip and GameTooltip.SetSpellByID then
                    GameTooltip:SetOwner(self, "ANCHOR_TOP")
                    GameTooltip:SetSpellByID(self.fsSpell)
                    GameTooltip:Show()
                elseif GameTooltip then
                    GameTooltip:SetOwner(self, "ANCHOR_TOP")
                    GameTooltip:AddLine("Leave this element out", MUTED[1], MUTED[2], MUTED[3])
                    GameTooltip:Show()
                end
            end)
            tile:SetScript("OnLeave", function() if GameTooltip then GameTooltip:Hide() end end)
            chooser.tiles[i] = tile
        end
        local item = items[i]
        if item then
            tile:ClearAllPoints()
            tile:SetPoint("LEFT", chooser, "LEFT", (3 + (i - 1) * (D.CHOOSER_TILE + 3)) * s, 0)
            tile:SetSize(size, size)
            tile.fsElement, tile.fsBase, tile.fsSpell = element, item.base, item.id
            if item.leave then
                tile.icon:SetColorTexture(0.04, 0.02, 0.09, 0.9)
                Mono(tile.text, 11, MUTED)
                tile.text:SetText("--")
                tile.text:Show()
            else
                tile.icon:SetTexture(item.icon)
                tile.text:Hide()
            end
            tile.mark:ClearAllPoints()
            tile.mark:SetPoint("BOTTOMLEFT", tile, "BOTTOMLEFT", 2 * s, 1 * s)
            tile.mark:SetPoint("BOTTOMRIGHT", tile, "BOTTOMRIGHT", -2 * s, 1 * s)
            tile.mark:SetHeight(2 * s)
            local c = ELEMENT[element] or WHITE
            tile.mark:SetColorTexture(c[1], c[2], c[3], 1)
            tile.mark:SetShown((item.leave and current == nil) or (not item.leave and current == item.base))
            tile:Show()
        elseif tile then
            tile:Hide()
        end
    end
    chooser:ClearAllPoints()
    chooser:SetPoint("TOPRIGHT", row, "TOPLEFT", -4 * s, 0)
    chooser:Show()
end

local function SeatCard()
    local s = Scale()
    local C = D.CARD
    card:SetSize(C.W * s, (C.TOP + C.ROWS * C.ROW + C.FOOT) * s)
    SeatEdges(card.edges, card, math.max(1, s))
    SetEdges(card.edges, VIOLET, 0.85)
    card.title:ClearAllPoints()
    card.title:SetPoint("TOPLEFT", card, "TOPLEFT", 8 * s, -4 * s)
    Mono(card.title, 10, MUTED)
    card.close:ClearAllPoints()
    card.close:SetPoint("TOPRIGHT", card, "TOPRIGHT", -3 * s, -2 * s)
    card.close:SetSize(14 * s, 14 * s)
    StyleButton(card.close, MUTED, "x", 11)
    card.name:ClearAllPoints()
    card.name:SetPoint("TOPLEFT", card, "TOPLEFT", 8 * s, -20 * s)
    card.name:SetSize((C.W - 16) * s, 18 * s)
    Mono(card.name, 12, WHITE)
    card.nameEdges = card.nameEdges or NewEdges(card.name, "BORDER", 0)
    SeatEdges(card.nameEdges, card.name, math.max(1, s))
    card.label:ClearAllPoints()
    card.label:SetPoint("TOPLEFT", card, "TOPLEFT", 8 * s, -45 * s)
    Mono(card.label, 9, MUTED)
    card.label:SetText("DROP ORDER")
    for i, row in ipairs(card.rows) do
        row:ClearAllPoints()
        row:SetPoint("TOPLEFT", card, "TOPLEFT", 8 * s, -(C.TOP + (i - 1) * C.ROW) * s)
        row:SetSize((C.W - 16) * s, (C.ROW - 3) * s)
        row.num:ClearAllPoints()
        row.num:SetPoint("LEFT", row, "LEFT", 6 * s, 0)
        Mono(row.num, 11, WHITE)
        row.bar:ClearAllPoints()
        row.bar:SetPoint("LEFT", row, "LEFT", 19 * s, 0)
        row.bar:SetSize(3 * s, 14 * s)
        row.tile:ClearAllPoints()
        row.tile:SetPoint("LEFT", row, "LEFT", 26 * s, 0)
        row.tile:SetSize(22 * s, 22 * s)
        row.label:ClearAllPoints()
        row.label:SetPoint("LEFT", row, "LEFT", 52 * s, 0)
        Mono(row.label, 10, WHITE)
        row.up:ClearAllPoints()
        row.up:SetPoint("RIGHT", row, "RIGHT", -22 * s, 0)
        row.up:SetSize(12 * s, 14 * s)
        row.down:ClearAllPoints()
        row.down:SetPoint("RIGHT", row, "RIGHT", -6 * s, 0)
        row.down:SetSize(12 * s, 14 * s)
        SeatEdges(row.edges, row, math.max(1, s))
    end
    card.delete:ClearAllPoints()
    card.delete:SetPoint("BOTTOMRIGHT", card, "BOTTOMRIGHT", -8 * s, 8 * s)
    card.delete:SetSize(58 * s, 17 * s)
    if card.useGnarly then
        card.useGnarly:ClearAllPoints()
        card.useGnarly:SetPoint("BOTTOMLEFT", card, "BOTTOMLEFT", 8 * s, 8 * s)
        card.useGnarly:SetSize(120 * s, 17 * s)
    end
end

local function BuildRow(parent, i)
    local row = CreateFrame("Frame", nil, parent)
    row.fill = row:CreateTexture(nil, "BACKGROUND")
    row.fill:SetAllPoints(row)
    row.edges = NewEdges(row, "BORDER", 0)
    row.num = row:CreateFontString(nil, "OVERLAY")
    row.bar = row:CreateTexture(nil, "ARTWORK")
    row.tile = CreateFrame("Button", nil, row)
    row.tile:RegisterForClicks("LeftButtonUp")
    row.tile.icon = row.tile:CreateTexture(nil, "ARTWORK")
    row.tile.icon:SetAllPoints(row.tile)
    row.tile.icon:SetTexCoord(0.07, 0.93, 0.07, 0.93)
    row.tile.text = row.tile:CreateFontString(nil, "OVERLAY")
    row.tile.text:SetPoint("CENTER", row.tile, "CENTER", 0, 0)
    row.label = row:CreateFontString(nil, "OVERLAY")
    row.up = NewButton(row, 12, 14)
    row.down = NewButton(row, 12, 14)
    row.tile:SetScript("OnClick", function() OpenChooser(row) end)
    row.up:SetScript("OnClick", function()
        local ok, why = Presets().Move(card.fsIndex, row.fsElement, -1)
        if ok == false then Refuse(why) end
        Dial.RefreshCard()
    end)
    row.down:SetScript("OnClick", function()
        local ok, why = Presets().Move(card.fsIndex, row.fsElement, 1)
        if ok == false then Refuse(why) end
        Dial.RefreshCard()
    end)
    return row
end

local function Commit()
    local PS = Presets()
    if not card or not card.fsIndex then return end
    local text = card.name:GetText()
    local preset = PS.Get(card.fsIndex)
    if preset and PS.CleanName(text) ~= preset.name and PS.CleanName(text) ~= "" then
        local ok, why = PS.Rename(card.fsIndex, text)
        if ok == false then Refuse(why) end
    end
end

local function BuildCard()
    if card then return card end
    local PS = Presets()
    card = CreateFrame("Frame", "FSTotemEditor", UIParent)
    card:SetFrameStrata("DIALOG")
    card:EnableMouse(true)
    card.fill = card:CreateTexture(nil, "BACKGROUND")
    card.fill:SetAllPoints(card)
    card.fill:SetColorTexture(0.051, 0.024, 0.125, 0.97)
    card.edges = NewEdges(card, "BORDER", 0)
    card.title = card:CreateFontString(nil, "OVERLAY")
    card.close = NewButton(card, 14, 14)
    card.close:SetScript("OnClick", function() Dial.CloseEditor() end)
    card.name = CreateFrame("EditBox", nil, card)
    card.name:SetAutoFocus(false)
    card.name:SetMaxLetters(PS.P.NAME_MAX)
    card.name:SetTextInsets(5, 5, 0, 0)
    card.name.fill = card.name:CreateTexture(nil, "BACKGROUND")
    card.name.fill:SetAllPoints(card.name)
    card.name.fill:SetColorTexture(0.039, 0.016, 0.086, 1)
    card.name:SetScript("OnEnterPressed", function(self)
        Commit()
        self:ClearFocus()
    end)
    card.name:SetScript("OnEscapePressed", function(self)
        Dial.RefreshCard()
        self:ClearFocus()
    end)
    card.name:SetScript("OnEditFocusGained", function(self)
        if self.fsFocus then return end
        self.fsFocus = true
        if card.nameEdges then SetEdges(card.nameEdges, CYAN, 1) end
    end)
    card.name:SetScript("OnEditFocusLost", function(self)
        self.fsFocus = false
        if card.nameEdges then SetEdges(card.nameEdges, CYAN, 0.4) end
        Commit()
    end)
    card.label = card:CreateFontString(nil, "OVERLAY")
    card.rows = {}
    for i = 1, D.CARD.ROWS do card.rows[i] = BuildRow(card, i) end
    card.delete = NewButton(card, 58, 17)
    card.delete:SetScript("OnClick", function(self)
        local now = GetTime and GetTime() or 0
        if card.fsConfirm and now - card.fsConfirm < D.CONFIRM then
            card.fsConfirm = nil
            local index = card.fsIndex
            Dial.CloseEditor()
            local ok, why = Presets().Delete(index)
            if ok == false then Refuse(why) end
        else
            card.fsConfirm = now
            StyleButton(self, PINK, "SURE?", 9)
        end
    end)
    card:SetScript("OnHide", function(self)
        CloseChooser()
        self.fsConfirm = nil
        if self.name.ClearFocus then self.name:ClearFocus() end
    end)
    if Dial.BuildCardExtras then Dial.BuildCardExtras(card) end
    SeatCard()
    if type(_G.UISpecialFrames) == "table" then table.insert(_G.UISpecialFrames, "FSTotemEditor") end
    card:Hide()
    return card
end

-- Repaints the card from the preset it edits.
function Dial.RefreshCard()
    if not (card and card.fsIndex) then return end
    local PS = Presets()
    local preset = PS.Get(card.fsIndex)
    if not preset then
        Dial.CloseEditor()
        return
    end
    SeatCard()
    card.title:SetText("PRESET " .. card.fsIndex)
    card.name:SetText(preset.name)
    SetEdges(card.nameEdges, CYAN, card.name.fsFocus and 1 or 0.4)
    local order = ElementOrder(preset)
    for i, row in ipairs(card.rows) do
        local element = order[i]
        row.fsElement = element
        local c = ELEMENT[element] or WHITE
        local entry = PS.Entry(element, preset.picks[element])
        local set = entry ~= nil
        row.fill:SetColorTexture(0.051, 0.024, 0.125, 0.6)
        SetEdges(row.edges, VIOLET, 0.35)
        row.num:SetText(set and tostring(i) or "-")
        row.bar:SetColorTexture(c[1], c[2], c[3], 1)
        if set then
            row.tile.icon:SetTexture(entry.icon)
            row.tile.icon:SetVertexColor(1, 1, 1, entry.known and 1 or 0.4)
            row.tile.text:Hide()
            row.label:SetText((entry.name:gsub(" Totem$", "")) .. (entry.known and "" or " (L" .. entry.level .. ")"))
            Tint(row.label, entry.known and WHITE or MUTED)
        else
            row.tile.icon:SetColorTexture(0.04, 0.02, 0.09, 0.5)
            row.tile.icon:SetVertexColor(1, 1, 1, 1)
            Mono(row.tile.text, 11, MUTED)
            row.tile.text:SetText("--")
            row.tile.text:Show()
            row.label:SetText("left out")
            Tint(row.label, MUTED)
        end
        StyleButton(row.up, MUTED, "^", 11)
        StyleButton(row.down, MUTED, "v", 11)
        row.up:SetShown(set and i > 1)
        row.down:SetShown(set and i < #preset.order)
    end
    StyleButton(card.delete, PINK, "DELETE", 9)
    if card.fsConfirm and (GetTime and GetTime() or 0) - card.fsConfirm >= D.CONFIRM then card.fsConfirm = nil end
    if Dial.RefreshCardExtras then Dial.RefreshCardExtras(card, preset) end
end

-- Opens the editor on preset `index` (out of combat).
function Dial.OpenEditor(index)
    local PS = Presets()
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    if not PS.Get(index) then return end
    BuildCard()
    card.fsIndex = index
    card.fsConfirm = nil
    card:ClearAllPoints()
    local tb = Totems()
    local anchor
    for _, def in ipairs({ "gnarly", "dial" }) do
        local button = tb.Button(def)
        if not anchor and button and button:IsShown() then anchor = button end
    end
    anchor = anchor or tb.Button("dial")
    card:SetPoint("BOTTOMRIGHT", anchor, "TOPRIGHT", 4.4 * Scale(), 21 * Scale())
    Dial.RefreshCard()
    card:Show()
end

-- Shift click on the dial: edits the active preset, or makes one on the NEW slot first.
function Dial.EditActive()
    local PS = Presets()
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    local index = PS.Active()
    if PS.IsNew(index) then
        local made, why = PS.Create()
        if not made then return Refuse(why) end
        index = made
    end
    Dial.OpenEditor(index)
end

-- Shift click on the GNARLY cell: edits its preset (nothing when it has none).
function Dial.EditGnarly()
    local PS = Presets()
    if InCombat() then return Refuse("Editing waits for combat to end.") end
    local index = PS.Gnarly()
    if index and PS.Get(index) then Dial.OpenEditor(index) end
end

-- USE AS GNARLY PRESET: a button on the card that ties the GNARLY cell to the preset it edits; again unties it.
function Dial.BuildCardExtras(c)
    local PS = Presets()
    c.useGnarly = NewButton(c, 120, 17)
    c.useGnarly:SetScript("OnClick", function()
        if not c.fsIndex then return end
        local on = PS.Gnarly() == c.fsIndex
        local ok, why = PS.SetGnarly(not on and c.fsIndex or nil)
        if ok == false then Refuse(why) end
        Dial.RefreshCard()
    end)
end

function Dial.RefreshCardExtras(c)
    local PS = Presets()
    local on = PS.Gnarly() == c.fsIndex
    StyleButton(c.useGnarly, on and PINK or MUTED, "USE AS GNARLY PRESET", 9)
    if on then
        c.useGnarly.fill:SetColorTexture(PINK[1] * 0.2 + 0.04, PINK[2] * 0.2 + 0.02, PINK[3] * 0.2 + 0.09, 0.9)
        SetEdges(c.useGnarly.edges, PINK, 0.9)
    else
        c.useGnarly.fill:SetColorTexture(0.051, 0.024, 0.125, 0.8)
    end
end

function Dial.Card()
    return card
end

function Dial.Chooser()
    return chooser
end

-------------------------------------------------------------------------------
-- Repaint and the ticker
-------------------------------------------------------------------------------

function Dial.Refresh()
    local tb = Totems()
    if not (tb and tb.Button) then return end
    Presets().InvalidateKnown()
    for _, def in ipairs(tb.Cells and tb.Cells() or {}) do
        local button = tb.Button(def.key)
        if button and button.fsArcs and button:IsShown() then Paint(button) end
    end
    PaintMarks()
    if card and card:IsShown() then Dial.RefreshCard() end
    local PS = Presets()
    if not pcall(PS.SyncSet2) then PS.Set2.state = "dead"; PS.Set2.why = "the set 2 sync raised" end
    PS.SaveState()
end

local function PaintCell(key)
    local tb = Totems()
    local button = tb and tb.Button(key)
    if button and button.fsArcs and button:IsShown() then Paint(button) end
end

-- The ticker: only the cell that is waiting (the dial: a queued switch or the applied flash, which also marks the
-- buttons) or flashing (GNARLY: the press flash) is painted, and once more when it stops.
local function Tick(self, elapsed)
    self.fsAcc = (self.fsAcc or 0) + (elapsed or 0)
    if self.fsAcc < D.TICK then return end
    self.fsAcc = 0
    local PS = Presets()
    PS.Expire()
    local pending = PS.Pending()
    local now = GetTime and GetTime() or 0
    local applied = PS.P.applied and PS.P.applied.at and now - PS.P.applied.at < PS.P.APPLIED_FLASH + D.TICK
    local age = PS.PressAge("gnarly")
    local pressed = age and age < PS.P.PRESS_FLASH + D.TICK
    local dialBusy = (pending or applied) and true or false
    local gnarlyBusy = pressed and true or false
    if dialBusy or self.fsWasDial then
        PaintCell("dial")
        PaintMarks()
    end
    if gnarlyBusy or self.fsWasGnarly then PaintCell("gnarly") end
    self.fsWasDial, self.fsWasGnarly = dialBusy, gnarlyBusy
end

local function OnPresetEvent(what)
    if what == "step" or what == "pending" or what == "applied" or what == "edited" or what == "regen" or what == "set2" then
        local tb = Totems()
        for _, def in ipairs(tb and tb.Cells and tb.Cells() or {}) do
            local button = tb.Button(def.key)
            if button and button.fsArcs and button:IsShown() then Paint(button) end
        end
        PaintMarks()
        if what == "edited" and card and card:IsShown() then Dial.RefreshCard() end
        Presets().SaveState()
    end
end

local function OnGameEvent(_, event, unit, _, spellId)
    local PS = Presets()
    if event == "UNIT_SPELLCAST_SUCCEEDED" then
        if unit == "player" then PS.OnCast(spellId) end
    elseif event == "PLAYER_REGEN_DISABLED" then
        Dial.CloseEditor()
    else
        PS.InvalidateKnown()        -- a learn event: the known totems may have changed
    end
end

local function Init()
    local PS = Presets()
    if not PS then return end
    PS.OnEvent(OnPresetEvent)
    local events = CreateFrame("Frame")
    events:RegisterEvent("UNIT_SPELLCAST_SUCCEEDED")
    events:RegisterEvent("PLAYER_REGEN_DISABLED")
    for _, learn in ipairs({ "SPELLS_CHANGED", "LEARNED_SPELL_IN_TAB", "PLAYER_LEVEL_UP", "PLAYER_ENTERING_WORLD" }) do
        events:RegisterEvent(learn)
    end
    events:SetScript("OnEvent", OnGameEvent)
    local ticker = CreateFrame("Frame", "FSTotemDialTicker")
    ticker:SetScript("OnUpdate", Tick)
    if FS.Config and FS.Config.OnChange then
        local function Apply()
            local tb = Totems()
            if FS.ClassShoulder and FS.ClassShoulder.Refresh then pcall(FS.ClassShoulder.Refresh) end
            if tb and tb.Sync then tb.Sync() end
        end
        FS.Config.OnChange(PS.SETTINGS.dial.key, Apply)
        FS.Config.OnChange(PS.SETTINGS.gnarly.key, Apply)
        FS.Config.OnChange(PS.SETTINGS.dialPlate.key, function() Dial.Refresh() end)
        FS.Config.OnChange(PS.SETTINGS.gnarlySet2.key, function() Dial.Refresh() end)
    end
end
Init()
